import assert from "node:assert/strict";
import {mkdirSync,writeFileSync} from "node:fs";
import {join} from "node:path";
import {ownedTmp} from "./src/kitlib/tmp.ts";
import {run} from "./src/kitlib/run.ts";
const owned=ownedTmp("cut-custom-native",{root:process.env.TMPDIR,bead:"ompkit-774u.55"});
const repo=owned.path,state=join(repo,"native-state"),foreign=join(repo,"foreign");mkdirSync(state);mkdirSync(foreign);
const db=join(state,"data.sqlite"),real=process.argv[1],binary=process.argv[2],cli=join(process.cwd(),"src/cli.ts");
const env={...process.env,HOME:repo,XDG_CONFIG_HOME:join(repo,"xdg"),BEADS_DB:db,BEADS_DIR:"",BR_REAL:real,AGENT_NAME:"CopperTrout"};delete env.OMP_KIT_FLEET_WATCH_CONFIG;
const decode=b=>new TextDecoder().decode(b);
async function br(args){const r=await run([real,"--db",db,...args,"--actor","CopperTrout"],{cwd:repo,env,deadline_s:30,max_output_bytes:1048576});assert.equal(r.rc,0,args.join(" ")+decode(r.stderr));return decode(r.stdout).trim();}
await br(["init"]);
const ac="- [ ] [a] [build] fixture behavior `true` -> rc 0";
const pin=(await br(["create","pin","--acceptance-criteria",ac,"--silent"])).split("\n").pop();
const other=(await br(["create","offcut","--acceptance-criteria",ac,"--silent"])).split("\n").pop();
async function probe(label,argv,id,rc,code,extra={}){const r=await run([...argv,"preflight","claim",id,"--actor","CopperTrout","--json"],{cwd:repo,env:{...env,...extra},deadline_s:30,max_output_bytes:1048576});const doc=JSON.parse(decode(r.stdout));const codes=(doc.data.findings??[]).map(f=>f.code);console.log(JSON.stringify({case:label,rc:r.rc,codes}));assert.equal(r.rc,rc,label+decode(r.stderr));assert.ok(codes.includes(code),JSON.stringify(doc));}
await probe("custom-native-source-stock",[process.execPath,cli],other,0,"CLAIM_CUT_ADMITTED");
await probe("custom-native-compiled-stock-no-Bun",[binary],other,0,"CLAIM_CUT_ADMITTED",{PATH:"/usr/bin:/bin"});
const config=join(repo,"fleet.json");env.OMP_KIT_FLEET_WATCH_CONFIG=config;
writeFileSync(config,JSON.stringify({sessions:[{repo:foreign,milestone:{epic:"elsewhere",pinned:[pin]}}]}));
await probe("custom-native-foreign-session",[process.execPath,cli],other,0,"CLAIM_CUT_ADMITTED");
writeFileSync(config,JSON.stringify({sessions:[{repo}]}));
await probe("custom-native-compiled-no-milestone",[binary],other,0,"CLAIM_CUT_ADMITTED",{PATH:"/usr/bin:/bin"});
writeFileSync(config,JSON.stringify({sessions:[{repo,milestone:{epic:"managed",pinned:[pin]}}]}));
await probe("custom-native-managed-source-offcut",[process.execPath,cli],other,1,"CLAIM_OUT_OF_CUT");
await probe("custom-native-managed-compiled-offcut",[binary],other,1,"CLAIM_OUT_OF_CUT",{PATH:"/usr/bin:/bin"});
await probe("custom-native-managed-pin",[binary],pin,0,"CLAIM_CUT_ADMITTED",{PATH:"/usr/bin:/bin"});
owned.cleanup();

